48	    /**
49	     * Formats an owner's salutation, as required by the API's read-only {@code salutation}
50	     * field: the owner's title and last name separated by a single space (e.g. {@code 'DR Who'})
51	     * when a title is present, or just the last name when no title was supplied.
52	     *
53	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
54	     * applied only where referenced via {@code qualifiedByName}.
55	     */
56	    /**
57	     * Formats an owner's self-link, as required by the API's read-only {@code selfLink}
58	     * field: the canonical API path {@code '/api/owners/'} followed by the owner's id.
59	     * Returns {@code null} when the owner has no id yet.
60	     *
61	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
62	     * applied only where referenced via {@code qualifiedByName}.
63	     */
64	    @Named("formatSelfLink")
65	    default String formatSelfLink(Owner owner) {
66	        if (owner == null || owner.getId() == null) {
67	            return null;
68	        }
69	        return "/api/owners/" + owner.getId();
70	    }
