72	    @Named("formatSalutation")
73	    default String formatSalutation(Owner owner) {
74	        if (owner == null) {
75	            return null;
76	        }
77	        String title = owner.getTitle();
78	        if (title == null || title.isEmpty()) {
79	            return owner.getLastName();
80	        }
81	        return title + " " + owner.getLastName();
82	    }
